package com.company.platform.inventory.infrastructure;
import com.company.platform.inventory.application.ReservationStore;import com.company.platform.inventory.domain.*;import java.math.BigDecimal;import java.sql.Timestamp;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class JdbcReservationStore implements ReservationStore {private final JdbcTemplate jdbc;public JdbcReservationStore(JdbcTemplate j){jdbc=j;}public ReservationRecord save(Reservation r,UUID inventoryId,BigDecimal q){jdbc.update("INSERT INTO reservations(id,tenant_id,order_id,reservation_reference,expires_at,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=?,updated_at=?",r.id(),r.tenantId(),r.orderId(),r.reference(),Timestamp.from(r.expiresAt()),r.status().name(),Timestamp.from(r.createdAt()),Timestamp.from(r.updatedAt()),r.status().name(),Timestamp.from(r.updatedAt()));jdbc.update("INSERT INTO reservation_items(id,tenant_id,reservation_id,inventory_id,quantity) VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET quantity=?",UUID.nameUUIDFromBytes((r.id()+"-"+inventoryId).getBytes()),r.tenantId(),r.id(),inventoryId,q,q);return new ReservationRecord(r,inventoryId,q);}private ReservationRecord map(java.sql.ResultSet x)throws java.sql.SQLException{UUID id=(UUID)x.getObject("id");Reservation r=Reservation.rehydrate(id,(UUID)x.getObject("tenant_id"),(UUID)x.getObject("order_id"),x.getString("reservation_reference"),ReservationStatus.valueOf(x.getString("status")),x.getTimestamp("expires_at").toInstant(),x.getTimestamp("created_at").toInstant(),x.getTimestamp("updated_at").toInstant());return new ReservationRecord(r,(UUID)x.getObject("inventory_id"),x.getBigDecimal("quantity"));}private List<ReservationRecord> q(String sql,Object...a){return jdbc.query(sql,(r,n)->map(r),a);}public Optional<ReservationRecord> find(UUID t,UUID id){return q("SELECT r.*,i.inventory_id,i.quantity FROM reservations r JOIN reservation_items i ON i.reservation_id=r.id WHERE r.tenant_id=? AND r.id=?",t,id).stream().findFirst();}public Optional<ReservationRecord> findByReference(UUID t,String ref){return q("SELECT r.*,i.inventory_id,i.quantity FROM reservations r JOIN reservation_items i ON i.reservation_id=r.id WHERE r.tenant_id=? AND r.reservation_reference=?",t,ref).stream().findFirst();}public List<ReservationRecord> findByOrder(UUID t,UUID order){return q("SELECT r.*,i.inventory_id,i.quantity FROM reservations r JOIN reservation_items i ON i.reservation_id=r.id WHERE r.tenant_id=? AND r.order_id=?",t,order);}public boolean reserveStock(UUID t,UUID id,BigDecimal q){return jdbc.update("UPDATE inventory SET reserved=reserved+?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND id=? AND on_hand-reserved-committed>=?",q,t,id,q)==1;}public boolean releaseStock(UUID t,UUID id,BigDecimal q){return jdbc.update("UPDATE inventory SET reserved=reserved-?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND id=? AND reserved>=?",q,t,id,q)==1;}public boolean consumeStock(UUID t,UUID id,BigDecimal q){return jdbc.update("UPDATE inventory SET reserved=reserved-?,on_hand=on_hand-?,updated_at=CURRENT_TIMESTAMP WHERE tenant_id=? AND id=? AND reserved>=? AND on_hand>=?",q,q,t,id,q,q)==1;}}
